/* Keep the hosted stylesheet independent of custom font files on the source system. */
body,
body * {
  font-family: Arial, sans-serif !important;
}

/* Embedded fonts for standalone hosting. */
@font-face {
  font-family: 'NotoSans';
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url('data:font/ttf;base64,') format('truetype');
}

@font-face {
  font-family: 'NotoSans';
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url('data:font/ttf;base64,') format('truetype');
}

@font-face {
  font-family: 'NotoSans';
  font-style: normal;
  font-weight: 600;
  font-display: swap;
  src: url('data:font/ttf;base64,') format('truetype');
}

@font-face {
  font-family: 'MMCDisplay';
  font-style: normal;
  font-weight: 700;
  font-display: swap;
  src: url('data:font/ttf;base64,') format('truetype');
}

